import React, { useState, useEffect, useCallback, useRef } from "react";

// ── Conexión real y compartida a Firebase Realtime Database ──
const FIREBASE_DB_URL = "https://the-cupule-7cd07-default-rtdb.firebaseio.com";

if (typeof window !== "undefined" && !window.storage) {
  window.storage = {
    async get(key) {
      try {
        const res = await fetch(`${FIREBASE_DB_URL}/${encodeURIComponent(key)}.json`);
        const data = await res.json();
        return data !== null ? { key, value: data } : null;
      } catch (e) { return null; }
    },
    async set(key, value) {
      try {
        await fetch(`${FIREBASE_DB_URL}/${encodeURIComponent(key)}.json`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(value),
        });
        return { key, value };
      } catch (e) { return null; }
    },
    async delete(key) {
      try {
        await fetch(`${FIREBASE_DB_URL}/${encodeURIComponent(key)}.json`, { method: "DELETE" });
        return { key, deleted: true };
      } catch (e) { return null; }
    },
    async list(prefix) {
      try {
        const res = await fetch(`${FIREBASE_DB_URL}/.json?shallow=true`);
        const data = await res.json();
        const keys = data ? Object.keys(data).filter((k) => !prefix || k.startsWith(prefix)) : [];
        return { keys };
      } catch (e) { return null; }
    },
  };
}


