function CornerFrame({ color = COLORS.white, size = 26, thickness = 3 }) {
  const base = { position: "absolute", width: size, height: size, borderColor: color, pointerEvents: "none" };
  const glow = `drop-shadow(0 0 4px ${color}88)`;
  return (
    <>
      <div style={{ ...base, top: -1, left: -1, borderTop: `${thickness}px solid ${color}`, borderLeft: `${thickness}px solid ${color}`, filter: glow }} />
      <div style={{ ...base, top: -1, right: -1, borderTop: `${thickness}px solid ${color}`, borderRight: `${thickness}px solid ${color}`, filter: glow }} />
      <div style={{ ...base, bottom: -1, left: -1, borderBottom: `${thickness}px solid ${color}`, borderLeft: `${thickness}px solid ${color}`, filter: glow }} />
      <div style={{ ...base, bottom: -1, right: -1, borderBottom: `${thickness}px solid ${color}`, borderRight: `${thickness}px solid ${color}`, filter: glow }} />
    </>
  );
}

